 6617 /// `checksum::hash_file` runs a whole file uninterruptibly; inside the
 6618 /// diff's blocking chunk that must yield to a dead session's abort
 6619 /// flag within one chunk).
 6620 fn hash_file_abortable(path: &Path, abort: &AtomicBool) -> Result<Vec<u8>> {
 6621     use std::io::Read;
